#!/usr/bin/env python3
"""Check the installed ABI against pinned upstream NinjaRS reference fixtures.

Usage: check_fixtures.py LIBRARY FIXTURE [--dp-limit 1e-6] [--qp]
Fixtures are read from TIRust's tests/fixtures/*_lanes.json; they are not
regenerated by this test. A refused DP lane is reported separately. Every QP
lane must succeed. The source fixture documents the truth and kinematic inputs.
"""
import argparse
import ctypes as c
import decimal
import json
from pathlib import Path


class Complex(c.Structure):
    _fields_ = [("re", c.c_double), ("im", c.c_double)]


def basis(rank):
    for degree in range(rank + 1):
        for t in range(degree, -1, -1):
            for x in range(degree - t, -1, -1):
                for y in range(degree - t - x, -1, -1):
                    yield t, x, y, degree - t - x - y


def records(values):
    return b"".join(format(decimal.Decimal.from_float(x), ".39E").encode().rjust(64)
                    for x in values)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("library", type=Path)
    parser.add_argument("fixture", type=Path)
    parser.add_argument("--dp-limit", type=float, default=1e-6)
    parser.add_argument("--qp", action="store_true")
    args = parser.parse_args()
    fixture = json.loads(args.fixture.read_text())
    lib = c.CDLL(str(args.library.resolve()))
    lib.ml_tirust_context_create.argtypes = [c.c_uint32, c.POINTER(c.c_void_p)]
    lib.ml_tirust_context_destroy.argtypes = [c.c_void_p]
    lib.ml_tirust_clear_cache.argtypes = [c.c_void_p]
    lib.ml_tirust_last_error.argtypes = [c.c_void_p, c.c_size_t]
    lib.ml_tirust_last_error.restype = c.c_size_t
    lib.ml_tirust_evaluate_dp.argtypes = [c.c_void_p, c.c_int32, c.c_int32,
        c.c_void_p, c.c_size_t, c.c_void_p, c.c_size_t, c.c_void_p, c.c_size_t,
        c.c_double, c.c_void_p, c.c_size_t, *([c.c_int32] * 4)]
    lib.ml_tirust_evaluate_mp.argtypes = [c.c_void_p, c.c_int32, c.c_int32,
        *([c.c_void_p, c.c_size_t] * 5), *([c.c_int32] * 4)]
    ctx = c.c_void_p()
    assert lib.ml_tirust_context_create(1, c.byref(ctx)) == 0
    report = {"fixture": str(args.fixture), "source": fixture["source"], "lanes": []}
    failed = False
    try:
        for lane in fixture["lanes"]:
            n, rank = lane["n"], lane["rank"]
            monomials = list(basis(rank))
            nc = len(monomials)
            p = [x for shift in lane["shifts"] for x in shift]
            s = [0.0] * (n * n)
            pair = iter(lane["invariants"])
            for i in range(n):
                for j in range(i + 1, n):
                    re, im = next(pair)
                    assert im == 0
                    s[i * n + j] = s[j * n + i] = re
            m = [x for mass in lane["masses"] for x in mass]
            numerator = {tuple(a): complex(*z) * (-1) ** sum(a)
                         for a, z in lane["coefficients"]}
            truth = [complex(*z) for z in lane["truth"]]
            for precision in (["dp", "qp"] if args.qp else ["dp"]):
                assert lib.ml_tirust_clear_cache(ctx) == 0
                if precision == "dp":
                    output = (Complex * (4 * nc))()
                    status = lib.ml_tirust_evaluate_dp(ctx, n, rank,
                        (c.c_double * len(p))(*p), len(p),
                        (c.c_double * len(s))(*s), len(s),
                        (Complex * n)(*(Complex(*z) for z in lane["masses"])), n,
                        lane["mu2"], output, 4 * nc, 0, 1, 0, 1)
                    values = [complex(z.re, z.im) for z in output]
                else:
                    pp, ss, mm, scale = (records(v) for v in (p, s, m, [lane["mu2"]]))
                    output = c.create_string_buffer(8 * nc * 64)
                    status = lib.ml_tirust_evaluate_mp(ctx, n, rank,
                        pp, len(pp), ss, len(ss), mm, len(mm), scale, len(scale),
                        output, len(output), 0, 1, 0, 1)
                    values = []
                    if status == 0:
                        numbers = [float(output.raw[i:i+64].strip())
                                   for i in range(0, len(output), 64)]
                        values = [complex(*numbers[i:i+2]) for i in range(0, len(numbers), 2)]
                row = {"label": lane["label"], "precision": precision, "status": status,
                       "n": n, "rank": rank,
                       "mass_type": "complex" if any(z[1] for z in lane["masses"]) else
                                    "massive" if any(z[0] for z in lane["masses"]) else "massless"}
                if status:
                    message = c.create_string_buffer(4096)
                    lib.ml_tirust_last_error(message, len(message))
                    row["message"] = message.value.decode()
                    failed |= status != 1 or precision == "qp"
                else:
                    slots = [sum(numerator.get(a, 0j) * values[k * nc + i]
                                 for i, a in enumerate(monomials)) for k in range(4)]
                    actual = [slots[3], slots[0] + slots[1], slots[2]]
                    error = max(abs(a - b) for a, b in zip(actual, truth)) / max(map(abs, truth))
                    row["relative_error"] = error
                    row["components"] = []
                    finite_scale = max(abs(actual[0]), abs(truth[0]))
                    for index, (label, value, reference) in enumerate(zip(
                            ("finite", "single_pole", "double_pole"), actual, truth)):
                        delta = abs(value - reference)
                        symmetric = delta / abs(value + reference) if value + reference else (
                            0.0 if delta == 0 else None)
                        ordinary = delta / abs(reference) if reference else (0.0 if delta == 0 else None)
                        small_pole = bool(index and finite_scale and
                            max(abs(value), abs(reference)) / finite_scale < 3e-6)
                        row["components"].append({"name": label,
                            "actual": [value.real, value.imag], "reference": [reference.real, reference.imag],
                            "absolute_difference": delta, "ordinary_relative_error": ordinary,
                            "symmetric_relative_error": symmetric, "small_pole_exception": small_pole,
                            "madloop_comparator_pass": (symmetric is not None and symmetric < 3e-6) or small_pole})
                    row["madloop_comparator_pass"] = all(v["madloop_comparator_pass"] for v in row["components"])
                    row["fixture_metric_target_1e8_pass"] = error <= 1e-8
                    failed |= error > (1e-8 if precision == "qp" else args.dp_limit)
                report["lanes"].append(row)
                print(json.dumps(row), flush=True)
    finally:
        assert lib.ml_tirust_context_destroy(ctx) == 0
    report["passed"] = not failed
    print(json.dumps({"upstream_criterion_passed": not failed, "evaluations": len(report["lanes"]),
        "madloop_comparator_failures": sum(r.get("madloop_comparator_pass") is False for r in report["lanes"]),
        "refused": sum(r["status"] != 0 for r in report["lanes"])}))
    raise SystemExit(1 if failed else 0)


if __name__ == "__main__":
    main()
